        },
        {
          "id": "d1_r1_c1",
          "component": "Text",
          "text": "08:30 - 09:00",
          "weight": 2
        },
        {
          "id": "d1_r1_c2",
          "component": "Text",
          "text": "Travel to the Colosseum",
          "weight": 3
        },
        {
          "id": "d1_r1_c3",
          "component": "Text",
          "text": "Take Metro Line B to the \"Colosseo\" station for direct access.",
          "weight": 5
