        {
          "id": "d1_r2",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r2_c1",
            "d1_r2_c2",
            "d1_r2_c3"
          ]
        },
        {
          "id": "d1_r2_c1",
          "component": "Text",
          "text": "09:00 - 11:30",
          "weight": 2
        },
        {
          "id": "d1_r2_c2",
          "component": "Text",
          "text": "Colosseum Tour",
          "weight": 3
        },
        {
          "id": "d1_r2_c3",
          "component": "Text",
          "text": "Book a 9:00 AM entry time. A guided tour or audio guide is highly recommended for families to bring the history to life.",
          "weight": 5
        },
        {
          "id": "d1_r3",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r3_c1",
            "d1_r3_c2",
            "d1_r3_c3"
          ]
        },
        {
          "id": "d1_r3_c1",
          "component": "Text",
          "text": "11:30 - 13:00",
          "weight": 2
        },
        {
          "id": "d1_r3_c2",
          "component": "Text",
          "text": "Roman Forum & Palatine Hill",
          "weight": 3
        },
        {
          "id": "d1_r3_c3",
          "component": "Text",
          "text": "Your Colosseum ticket includes entry. Explore the heart of ancient Roman life and enjoy panoramic views from Palatine Hill.",
          "weight": 5
        },
        {
          "id": "d1_r4",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r4_c1",
            "d1_r4_c2",
            "d1_r4_c3"
          ]
        },
        {
          "id": "d1_r4_c1",
          "component": "Text",
          "text": "13:00 - 14:30",
          "weight": 2
        },
        {
          "id": "d1_r4_c2",
          "component": "Text",
          "text": "Lunch Break",
          "weight": 3
        },
        {
          "id": "d1_r4_c3",
          "component": "Text",
          "text": "Find a trattoria in the side streets away from the main attractions for better value and authenticity.",
          "weight": 5
        },
        {
          "id": "d1_r5",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r5_c1",
            "d1_r5_c2",
            "d1_r5_c3"
          ]
        },
        {
          "id": "d1_r5_c1",
          "component": "Text",
          "text": "14:30 - 16:30",
          "weight": 2
        },
        {
          "id": "d1_r5_c2",
          "component": "Text",
          "text": "Capitoline Hill & Museums",
          "weight": 3
        },
        {
          "id": "d1_r5_c3",
          "component": "Text",
          "text": "Walk to the top of Capitoline Hill for a stunning, free view over the Roman Forum. The Capitoline Museums are optional but excellent.",
          "weight": 5
        },
        {
          "id": "d1_r6",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r6_c1",
            "d1_r6_c2",
            "d1_r6_c3"
          ]
        },
        {
          "id": "d1_r6_c1",
          "component": "Text",
          "text": "16:30 - 18:00",
          "weight": 2
        },
        {
          "id": "d1_r6_c2",
          "component": "Text",
          "text": "Piazza Venezia & Vittoriano",
          "weight": 3
        },
        {
          "id": "d1_r6_c3",
          "component": "Text",
          "text": "See the massive Altare della Patria (Altar of the Fatherland). You can take a glass elevator to the top for a 360-degree view of Rome.",
          "weight": 5
        },
        {
          "id": "d1_r7",
          "component": "Row",
          "align": "start",
          "children": [
            "d1_r7_c1",
            "d1_r7_c2",
            "d1_r7_c3"
          ]
        },
        {
          "id": "d1_r7_c1",
          "component": "Text",
          "text": "18:00 - 19:00",
          "weight": 2
        },
        {
          "id": "d1_r7_c2",
          "component": "Text",
          "text": "Relax & Return",
          "weight": 3
        },
        {
          "id": "d1_r7_c3",
          "component": "Text",
          "text": "Enjoy a gelato and a leisurely stroll before heading back to your accommodation.",
          "weight": 5
        },
