        },
        {
          "id": "d2_r1_c1",
          "component": "Text",
          "text": "08:30 - 09:00",
          "weight": 2
        },
        {
          "id": "d2_r1_c2",
          "component": "Text",
          "text": "Travel to Vatican City",
          "weight": 3
        },
        {
          "id": "d2_r1_c3",
          "component": "Text",
          "text": "Take Metro Line A to \"Ottaviano-S. Pietro\". It's a 10-minute walk from the station to the Vatican Museums entrance.",
          "weight": 5
        },
        {
          "id": "d2_r2",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r2_c1",
            "d2_r2_c2",
            "d2_r2_c3"
          ]
        },
        {
          "id": "d2_r2_c1",
          "component": "Text",
          "text": "09:00 - 12:30",
          "weight": 2
        },
        {
          "id": "d2_r2_c2",
          "component": "Text",
          "text": "Vatican Museums & Sistine Chapel",
          "weight": 3
        },
        {
          "id": "d2_r2_c3",
          "component": "Text",
          "text": "Book the first possible entry time (e.g., 9:00 AM). Follow the main path to the Sistine Chapel, but don't miss the Gallery of Maps and Raphael Rooms.",
          "weight": 5
        },
        {
          "id": "d2_r3",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r3_c1",
            "d2_r3_c2",
            "d2_r3_c3"
          ]
        },
        {
          "id": "d2_r3_c1",
          "component": "Text",
          "text": "12:30 - 13:00",
          "weight": 2
        },
        {
          "id": "d2_r3_c2",
          "component": "Text",
          "text": "Walk to St. Peter's Square",
          "weight": 3
        },
        {
          "id": "d2_r3_c3",
          "component": "Text",
          "text": "Exit the museums and walk around the Vatican walls to the entrance of St. Peter's Square.",
          "weight": 5
        },
        {
          "id": "d2_r4",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r4_c1",
            "d2_r4_c2",
            "d2_r4_c3"
          ]
        },
        {
          "id": "d2_r4_c1",
          "component": "Text",
          "text": "13:00 - 14:30",
          "weight": 2
        },
        {
          "id": "d2_r4_c2",
          "component": "Text",
          "text": "Lunch Break",
          "weight": 3
        },
        {
          "id": "d2_r4_c3",
          "component": "Text",
          "text": "Eat in the nearby Prati neighborhood, which has many non-touristy options. Avoid the restaurants directly next to the Vatican.",
          "weight": 5
        },
        {
          "id": "d2_r5",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r5_c1",
            "d2_r5_c2",
            "d2_r5_c3"
          ]
        },
        {
          "id": "d2_r5_c1",
          "component": "Text",
          "text": "14:30 - 17:00",
          "weight": 2
        },
        {
          "id": "d2_r5_c2",
          "component": "Text",
          "text": "St. Peter's Basilica",
          "weight": 3
        },
        {
          "id": "d2_r5_c3",
          "component": "Text",
          "text": "Entry is free, but you must pass through a security line. Dress code is strictly enforced: cover shoulders and knees.",
          "weight": 5
        },
        {
          "id": "d2_r6",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r6_c1",
            "d2_r6_c2",
            "d2_r6_c3"
          ]
        },
        {
          "id": "d2_r6_c1",
          "component": "Text",
          "text": "17:00 - 18:30",
          "weight": 2
        },
        {
          "id": "d2_r6_c2",
          "component": "Text",
          "text": "St. Peter's Dome Climb",
          "weight": 3
        },
        {
          "id": "d2_r6_c3",
          "component": "Text",
          "text": "Optional, but the view is unforgettable. There is a fee and a choice between stairs or an elevator for the first half.",
          "weight": 5
        },
        {
          "id": "d2_r7",
          "component": "Row",
          "align": "start",
          "children": [
            "d2_r7_c1",
            "d2_r7_c2",
            "d2_r7_c3"
          ]
        },
        {
          "id": "d2_r7_c1",
          "component": "Text",
          "text": "18:30 - 19:00",
          "weight": 2
        },
        {
          "id": "d2_r7_c2",
          "component": "Text",
          "text": "St. Peter's Square",
          "weight": 3
        },
        {
          "id": "d2_r7_c3",
          "component": "Text",
          "text": "Absorb the evening atmosphere in the magnificent square designed by Bernini.",
          "weight": 5
        },
