        {
          "id": "d3_r1_c2",
          "component": "Text",
          "text": "Travel to the Spanish Steps",
          "weight": 3
        },
        {
          "id": "d3_r1_c3",
          "component": "Text",
          "text": "Take Metro Line A to \"Spagna\". You will exit directly at the base of the steps.",
