        {
          "id": "d3_r2_c2",
          "component": "Text",
          "text": "Spanish Steps & Piazza di Spagna",
          "weight": 3
        },
        {
          "id": "d3_r2_c3",
          "component": "Text",
          "text": "Climb the steps for a great view. The area is quieter in the morning. Explore the surrounding high-end shopping streets.",
          "weight": 5
